<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>欧姆定律：电压、电阻与电流</title>
<style>
  :root{--bg:#0f1720;--fg:#e8eef5;--accent:#4fc3f7;--muted:#8aa0b4;--panel:#18232e;
        --volt:#ffb74d;--res:#8e9bff;--cur:#66bb6a;--warn:#ef5350;}
  *{box-sizing:border-box;}
  body{margin:0;background:var(--bg);color:var(--fg);font-family:system-ui,-apple-system,"Segoe UI",sans-serif;padding:16px;}
  h1{font-size:1.15rem;margin:0 0 4px;}
  .sub{color:var(--muted);font-size:.85rem;margin-bottom:14px;line-height:1.5;}
  .wrap{display:grid;grid-template-columns:1fr 320px;gap:16px;align-items:start;}
  @media(max-width:820px){.wrap{grid-template-columns:1fr;}}
  .card{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:10px;}
  canvas{width:100%;height:auto;display:block;border-radius:6px;background:#0b131b;}
  .panel{background:var(--panel);border:1px solid #263646;border-radius:10px;padding:14px;}
  .ctrl{margin-bottom:14px;}
  .ctrl:last-of-type{margin-bottom:0;}
  label{display:flex;justify-content:space-between;align-items:baseline;font-size:.9rem;margin-bottom:6px;}
  .val{color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  input[type=range]{width:100%;accent-color:var(--accent);}
  .readout{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px;}
  .mini{background:#0b131b;border:1px solid #223141;border-radius:8px;padding:8px 10px;}
  .mini .k{font-size:.72rem;color:var(--muted);}
  .mini .v{font-size:.95rem;color:var(--accent);font-variant-numeric:tabular-nums;font-weight:600;}
  .mini.wide{grid-column:1 / -1;}
  .assume{font-size:.75rem;color:var(--muted);line-height:1.6;margin-top:12px;border-top:1px dashed #2c3d4e;padding-top:9px;}
  .assume b{color:#c7d6e4;}
  .legend{display:flex;flex-wrap:wrap;gap:10px;font-size:.75rem;color:var(--muted);margin-top:8px;}
  .legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:4px;vertical-align:middle;}
  .hint{font-size:.75rem;color:var(--muted);margin-top:8px;line-height:1.5;}
</style>
</head>
<body>
  <h1>欧姆定律：电压、电阻与电流</h1>
  <div class="sub">调节电压 U 与电阻 R，实时观察电流 I = U / R、功率与灯泡亮度，并查看 I–U 与 I–R 关系曲线。</div>

  <div class="wrap">
    <div class="card">
      <canvas id="cv" width="900" height="600" aria-label="欧姆定律电路与关系曲线"></canvas>
      <div class="legend">
        <span><i style="background:#ffb74d"></i>电压 U</span>
        <span><i style="background:#8e9bff"></i>电阻 R</span>
        <span><i style="background:#66bb6a"></i>电流 I</span>
      </div>
    </div>

    <div class="panel">
      <div class="ctrl">
        <label for="u">电压 U <span class="val" id="uOut">6.0 V</span></label>
        <input id="u" type="range" min="0.5" max="24" step="0.1" value="6">
      </div>
      <div class="ctrl">
        <label for="r">电阻 R <span class="val" id="rOut">12.0 Ω</span></label>
        <input id="r" type="range" min="1" max="60" step="0.5" value="12">
      </div>

      <div class="readout">
        <div class="mini"><div class="k">电流 I = U/R</div><div class="v" id="curV">0.500 A</div></div>
        <div class="mini"><div class="k">功率 P = UI</div><div class="v" id="powV">3.00 W</div></div>
        <div class="mini"><div class="k">电导 G = 1/R</div><div class="v" id="condV">0.083 S</div></div>
        <div class="mini"><div class="k">灯泡亮度</div><div class="v" id="brightV">中等</div></div>
      </div>

      <div class="hint">提示：固定 R 时 I 与 U 成正比（过原点直线）；固定 U 时 I 与 R 成反比（双曲线）。电阻翻倍，电流减半。</div>

      <div class="assume">
        <b>数学假设：</b>理想线性电阻，严格满足 \(I=U/R\)，R 为常数、不随温度或电压变化（无热效应、无非欧姆行为）。
        功率按 \(P=UI=U^2/R=I^2R\) 计算。电路为简单串联回路，忽略电源内阻、导线电阻与接触电阻。
        亮度仅作定性示意（与功率对数映射），不代表真实光通量。
      </div>
    </div>
  </div>

<script>
(function(){
  const cv = document.getElementById("cv");
  const ctx = cv.getContext("2d");
  const uEl = document.getElementById("u");
  const rEl = document.getElementById("r");
  const uOut = document.getElementById("uOut");
  const rOut = document.getElementById("rOut");
  const curV = document.getElementById("curV");
  const powV = document.getElementById("powV");
  const condV = document.getElementById("condV");
  const brightV = document.getElementById("brightV");

  function restore(){
    let s = {};
    try { s = genui.getState() || {}; } catch(e){ s = {}; }
    uEl.value = (typeof s.u === "number") ? s.u : 6;
    rEl.value = (typeof s.r === "number") ? s.r : 12;
  }
  function save(){
    try { genui.setState({ u: Number(uEl.value), r: Number(rEl.value) }); } catch(e){}
  }

  function brightnessLabel(P){
    if(P < 0.5) return "很暗";
    if(P < 2) return "较暗";
    if(P < 6) return "中等";
    if(P < 15) return "较亮";
    return "很亮";
  }

  function draw(){
    const U = Number(uEl.value);
    const R = Number(rEl.value);
    const I = U / R;
    const P = U * I;
    const G = 1 / R;

    uOut.textContent = U.toFixed(1) + " V";
    rOut.textContent = R.toFixed(1) + " Ω";
    curV.textContent = I.toFixed(3) + " A";
    powV.textContent = P.toFixed(2) + " W";
    condV.textContent = G.toFixed(3) + " S";
    brightV.textContent = brightnessLabel(P);

    const W = cv.width, H = cv.height;
    ctx.clearRect(0,0,W,H);
    ctx.fillStyle = "#0b131b";
    ctx.fillRect(0,0,W,H);

    // ===== 上部：电路示意 =====
    const circuitH = 210;
    const cx = W/2, cyC = circuitH/2 + 8;

    // 导线矩形
    ctx.strokeStyle = "#3a5570";
    ctx.lineWidth = 3;
    ctx.strokeRect(W*0.22, 44, W*0.56, circuitH - 80);

    // 电池（左侧）
    const batX = W*0.22, batY = cyC;
    ctx.fillStyle = "#ffb74d";
    ctx.fillRect(batX - 5, batY - 26, 8, 52);
    ctx.fillStyle = "#ffe0a3";
    ctx.fillRect(batX + 3, batY - 16, 5, 32);
    ctx.fillStyle = "#ffb74d";
    ctx.font = "13px system-ui, sans-serif";
    ctx.textAlign = "right";
    ctx.fillText("U = " + U.toFixed(1) + " V", batX - 14, batY - 22);

    // 电阻（右侧）
    const resX = W*0.78, resY = cyC;
    ctx.fillStyle = "#8e9bff";
    ctx.fillRect(resX - 14, resY - 24, 28, 48);
    ctx.strokeStyle = "#c3ccff";
    ctx.lineWidth = 1.5;
    for(let i=0;i<4;i++){
      const y = resY - 16 + i*11;
      ctx.beginPath(); ctx.moveTo(resX - 14, y); ctx.lineTo(resX + 14, y); ctx.stroke();
    }
    ctx.fillStyle = "#8e9bff";
    ctx.textAlign = "left";
    ctx.fillText("R = " + R.toFixed(1) + " Ω", resX + 22, resY - 22);

    // 灯泡（顶部中央）
    const bulbX = cx, bulbY = 44;
    const glow = Math.min(1, Math.log10(1 + P) / 1.6);
    if(glow > 0.02){
      const rad = 26 + 30 * glow;
      const g = ctx.createRadialGradient(bulbX, bulbY, 4, bulbX, bulbY, rad);
      g.addColorStop(0, "rgba(255,240,150," + (0.55*glow) + ")");
      g.addColorStop(1, "rgba(255,240,150,0)");
      ctx.fillStyle = g;
      ctx.beginPath(); ctx.arc(bulbX, bulbY, rad, 0, Math.PI*2); ctx.fill();
    }
    ctx.beginPath();
    ctx.arc(bulbX, bulbY, 17, 0, Math.PI*2);
    ctx.fillStyle = "rgba(255,238,150," + (0.25 + 0.75*glow) + ")";
    ctx.fill();
    ctx.strokeStyle = "#ffd54f";
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.fillStyle = "#8aa0b4";
    ctx.font = "12px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("亮度：" + brightnessLabel(P) + "（P = " + P.toFixed(2) + " W）", bulbX, bulbY - 28);

    // 电流箭头（沿导线，数量随 I 增加）
    const nArrows = Math.max(1, Math.min(14, Math.round(I * 6)));
    const path = [];
    // 沿矩形逆时针铺点：底边右→左，左边下→上，顶边左→右，右边上→下
    const L = W*0.22, Rt = W*0.78, Tp = 44, Bt = circuitH - 36;
    for(let i=0;i<=40;i++) path.push([L + (Rt-L)*(1 - i/40), Bt]);   // 底边 右→左
    for(let i=0;i<=20;i++) path.push([L, Bt - (Bt-Tp)*(i/20)]);        // 左边 下→上
    for(let i=0;i<=40;i++) path.push([L + (Rt-L)*(i/40), Tp]);          // 顶边 左→右
    for(let i=0;i<=20;i++) path.push([Rt, Tp + (Bt-Tp)*(i/20)]);        // 右边 上→下

    ctx.fillStyle = "#66bb6a";
    for(let k=0;k<nArrows;k++){
      const idx = Math.floor(path.length * k / nArrows);
      const p = path[Math.min(idx, path.length-1)];
      const p2 = path[Math.min(idx+1, path.length-1)];
      const dx = p2[0]-p[0], dy = p2[1]-p[1];
      const len = Math.hypot(dx,dy) || 1;
      const ux = dx/len, uy = dy/len;
      const ax = p[0], ay = p[1];
      const s = 6;
      ctx.beginPath();
      ctx.moveTo(ax + ux*s, ay + uy*s);
      ctx.lineTo(ax - ux*s - uy*s*0.7, ay - uy*s + ux*s*0.7);
      ctx.lineTo(ax - ux*s + uy*s*0.7, ay - uy*s - ux*s*0.7);
      ctx.closePath();
      ctx.fill();
    }

    // 电流读数
    ctx.fillStyle = "#66bb6a";
    ctx.font = "bold 14px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("I = " + I.toFixed(3) + " A", cx, Bt - 12);

    // ===== 下部：两张关系曲线 =====
    const lowerTop = circuitH + 16;
    const lowerH = H - lowerTop - 36;
    const gap = 40;
    const halfW = (W - gap) / 2;

    function axisBox(ox, oy, bw, bh, title, xLabel, yLabel){
      ctx.fillStyle = "#18232e";
      ctx.fillRect(ox, oy, bw, bh);
      ctx.strokeStyle = "#2c3d4e";
      ctx.lineWidth = 1;
      ctx.strokeRect(ox, oy, bw, bh);
      ctx.fillStyle = "#e8eef5";
      ctx.font = "12px system-ui, sans-serif";
      ctx.textAlign = "left";
      ctx.fillText(title, ox + 8, oy + 16);
      ctx.fillStyle = "#8aa0b4";
      ctx.textAlign = "center";
      ctx.fillText(xLabel, ox + bw/2, oy + bh + 16);
      ctx.save();
      ctx.translate(ox + 12, oy + bh/2);
      ctx.rotate(-Math.PI/2);
      ctx.fillText(yLabel, 0, 0);
      ctx.restore();
    }

    // 左图：I–U（固定当前 R）
    {
      const ox = 0, oy = lowerTop, bw = halfW, bh = lowerH;
      axisBox(ox, oy, bw, bh, "I–U 关系（R 固定）", "U (V)", "I (A)");
      const Umax = 24, Imax = Math.max(0.5, Umax / R);
      const px = 46, pr = 16, pt = 28, pb = 26;
      const plotW = bw - px - pr, plotH = bh - pt - pb;
      const X = u => ox + px + (u / Umax) * plotW;
      const Y = i => oy + pt + (1 - i / Imax) * plotH;

      // 轴
      ctx.strokeStyle = "#36506a";
      ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Umax), Y(0)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Imax)); ctx.stroke();

      // 直线 I = U/R
      ctx.strokeStyle = "#66bb6a";
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Umax), Y(Umax/R)); ctx.stroke();

      // 当前点
      ctx.fillStyle = "#ffb74d";
      ctx.beginPath(); ctx.arc(X(U), Y(I), 5, 0, Math.PI*2); ctx.fill();

      ctx.fillStyle = "#8aa0b4";
      ctx.font = "11px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("0", X(0), Y(0) + 14);
      ctx.fillText(Umax + " V", X(Umax), Y(0) + 14);
      ctx.textAlign = "right";
      ctx.fillText(Imax.toFixed(2) + " A", X(0) - 5, Y(Imax) + 4);
    }

    // 右图：I–R（固定当前 U）
    {
      const ox = halfW + gap, oy = lowerTop, bw = halfW, bh = lowerH;
      axisBox(ox, oy, bw, bh, "I–R 关系（U 固定）", "R (Ω)", "I (A)");
      const Rmax = 60;
      const Imax = Math.max(0.2, U / 1); // R 最小 1
      const px = 46, pr = 16, pt = 28, pb = 26;
      const plotW = bw - px - pr, plotH = bh - pt - pb;
      const X = r => ox + px + (r / Rmax) * plotW;
      const Y = i => oy + pt + (1 - i / Imax) * plotH;

      ctx.strokeStyle = "#36506a";
      ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Rmax), Y(0)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Imax)); ctx.stroke();

      // 曲线 I = U/R
      ctx.strokeStyle = "#66bb6a";
      ctx.lineWidth = 2;
      ctx.beginPath();
      const N = 200;
      for(let i=1;i<=N;i++){
        const rr = 1 + (Rmax - 1) * i / N;
        const ii = U / rr;
        const sx = X(rr), sy = Y(ii);
        if(i===1) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
      }
      ctx.stroke();

      // 当前点
      ctx.fillStyle = "#ffb74d";
      ctx.beginPath(); ctx.arc(X(R), Y(I), 5, 0, Math.PI*2); ctx.fill();

      ctx.fillStyle = "#8aa0b4";
      ctx.font = "11px system-ui, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("0", X(0), Y(0) + 14);
      ctx.fillText(Rmax + " Ω", X(Rmax), Y(0) + 14);
      ctx.textAlign = "right";
      ctx.fillText(Imax.toFixed(2) + " A", X(0) - 5, Y(Imax) + 4);
    }
  }

  function onChange(){ draw(); save(); }

  uEl.addEventListener("input", onChange);
  rEl.addEventListener("input", onChange);

  restore();
  draw();
  save();
})();
</script>
</body>
</html>

怎么读这个实验

电压 U 增大（固定 R）：电流按比例增大，灯泡变亮，功率上升。左下 I–U 图中绿色直线为过原点直线，斜率就是 1/R。

电阻 R 增大（固定 U）：电流按比例减小，灯泡变暗。右下 I–R 图是双曲线，R 翻倍则 I 减半。

电导 G = 1/R：是电阻的倒数，R 越大电导越小；I = U·G，电导越大越“容易”通过电流。

功率 P = UI：反映能量消耗速率，也是亮度示意的依据；同样电压下电阻越小，功率越大、越亮。

假设说明

电阻为理想线性电阻，阻值恒定，不随温度、电压或电流变化（忽略白炽灯灯丝升温导致阻值上升的非欧姆效应）。

电路为简单串联闭合回路，忽略电源内阻、导线电阻、接触电阻与电感/电容效应，电流处处相等。

